ALTER TABLE "Vehicle" ADD COLUMN "catalogCarId" TEXT REFERENCES "MarketCar"(id) ON DELETE SET NULL, ADD COLUMN "productionYear" INTEGER, ADD COLUMN mileage INTEGER NOT NULL DEFAULT 0 CHECK (mileage BETWEEN 0 AND 2000000);
CREATE TABLE "MaintenanceRecord" (id TEXT PRIMARY KEY,"vehicleId" TEXT NOT NULL REFERENCES "Vehicle"(id) ON DELETE CASCADE,"serviceCode" TEXT NOT NULL,mileage INTEGER NOT NULL CHECK(mileage BETWEEN 0 AND 2000000),"performedAt" TIMESTAMP(3) NOT NULL,"intervalKm" INTEGER CHECK("intervalKm">0),"intervalMonths" INTEGER CHECK("intervalMonths">0),note TEXT NOT NULL DEFAULT '',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "MaintenanceRecord_vehicleId_serviceCode_performedAt_idx" ON "MaintenanceRecord"("vehicleId","serviceCode","performedAt");
CREATE TABLE "SupportTicket" (id TEXT PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES "User"(id) ON DELETE CASCADE,department TEXT NOT NULL CHECK(department IN ('TECHNICAL','ROADSIDE','HALL','MARKET','PAYMENTS','GENERAL')),subject TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'OPEN' CHECK(status IN ('OPEN','WAITING_CUSTOMER','CLOSED')),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "SupportTicket_userId_updatedAt_idx" ON "SupportTicket"("userId","updatedAt");
CREATE INDEX "SupportTicket_status_department_updatedAt_idx" ON "SupportTicket"(status,department,"updatedAt");
CREATE TABLE "SupportMessage" (id TEXT PRIMARY KEY,"ticketId" TEXT NOT NULL REFERENCES "SupportTicket"(id) ON DELETE CASCADE,sender TEXT NOT NULL CHECK(sender IN ('CUSTOMER','EXPERT')),body TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "SupportMessage_ticketId_createdAt_id_idx" ON "SupportMessage"("ticketId","createdAt",id);
